+import { generateSchema, generateTypeDefinitions } from "../src/db/schema.ts";
+import { writeFileSync } from "fs";
+import { resolve } from "path";
+
+const connectionString = process.env.DATABASE_URL;
+if (!connectionString) {
+  throw new Error("DATABASE_URL environment variable is required");
+}
+
+async function main() {
+  try {
+    console.log("Introspecting database schema...");
+    const schema = await generateSchema(connectionString);
+
+    console.log("Generating TypeScript types...");
+    const types = generateTypeDefinitions(schema);
+
+    const outputPath = resolve("src/db/types.ts");
+    writeFileSync(outputPath, types, "utf-8");
+
+    console.log(`✓ Generated types at ${outputPath}`);
+    console.log(`✓ ${Object.keys(schema).length} tables processed`);
+  } catch (error) {
+    console.error("Error generating schema:", error);
+    process.exit(1);
+  }
+}
+
+main();
