diff --git a/src/db/schema.ts b/src/db/schema.ts
new file mode 100644
index 0000000..9755cfd
--- /dev/null
+++ b/src/db/schema.ts
@@ -0,0 +1,99 @@
+import { Pool } from "pg";
+
+interface ColumnInfo {
+  name: string;
+  type: string;
+  nullable: boolean;
+}
+
+interface TableSchema {
+  [tableName: string]: {
+    columns: ColumnInfo[];
+  };
+}
+
+const pgTypeToTS: Record<string, string> = {
+  bigint: "number | string",
+  integer: "number",
+  smallint: "number",
+  decimal: "number | string",
+  numeric: "number | string",
+  real: "number",
+  "double precision": "number",
+  text: "string",
+  varchar: "string",
+  char: "string",
+  boolean: "boolean",
+  timestamp: "Date",
+  "timestamp with time zone": "Date",
+  date: "Date",
+  time: "string",
+  json: "Record<string, any>",
+  jsonb: "Record<string, any>",
+  uuid: "string",
+};
+
+function pgToTsType(pgType: string): string {
+  return pgTypeToTS[pgType] || "unknown";
+}
+
+export async function generateSchema(connectionString: string): Promise<TableSchema> {
+  const pool = new Pool({ connectionString });
+
+  try {
+    const result = await pool.query(`
+      SELECT
+        t.table_name,
+        c.column_name,
+        c.data_type,
+        c.is_nullable
+      FROM information_schema.tables t
+      JOIN information_schema.columns c ON t.table_name = c.table_name
+      WHERE t.table_schema = 'public'
+      ORDER BY t.table_name, c.ordinal_position
+    `);
+
+    const schema: TableSchema = {};
+
+    for (const row of result.rows) {
+      const tableName = row.table_name;
+      if (!schema[tableName]) {
+        schema[tableName] = { columns: [] };
+      }
+
+      schema[tableName].columns.push({
+        name: row.column_name,
+        type: pgToTsType(row.data_type),
+        nullable: row.is_nullable === "YES",
+      });
+    }
+
+    return schema;
+  } finally {
+    await pool.end();
+  }
+}
+
+export function generateTypeDefinitions(schema: TableSchema): string {
+  let output = "// Generated from database schema. Do not edit manually.\n\n";
+
+  for (const [tableName, tableInfo] of Object.entries(schema)) {
+    const interfaceName = tableNameToInterface(tableName);
+
+    output += `export interface ${interfaceName} {\n`;
+    for (const col of tableInfo.columns) {
+      const typeStr = col.nullable ? `${col.type} | null` : col.type;
+      output += `  ${col.name}: ${typeStr};\n`;
+    }
+    output += "}\n\n";
+  }
+
+  return output;
+}
+
+function tableNameToInterface(name: string): string {
+  return name
+    .split("_")
+    .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
+    .join("");
+}
